<?php

declare(strict_types=1);

namespace Database\Seeders;

use Carbon\CarbonImmutable;
use Illuminate\Database\Console\Seeds\WithoutModelEvents;
use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\Storage;
use Modules\Media\Models\Media;
use Modules\Works\Models\Work;

/**
 * generated by agentcms figma apply (fingerprint c13a44d9d90e) — Figma design の Design Fixture データ。
 * Figma のサンプルテキスト（WORKS A 等）を CMS へ投入する（Content Source は CMS: SPEC §45）。
 * body は Figma design に存在しないため空（内容を捏造しない — schema override で必須解除済み）。
 * 実行: php artisan db:seed --class=Database\\Seeders\\FigmaContentSeeder
 */
class FigmaContentSeeder extends Seeder
{
    use WithoutModelEvents;

    public function run(): void
    {
        $works = [
            ['title' => 'WORKS A', 'slug' => 'works-a', 'category' => 'branding', 'date' => '2026-04-01', 'image' => 'img-imgrefw1.png', 'order' => 0],
            ['title' => 'WORKS B', 'slug' => 'works-b', 'category' => 'web', 'date' => '2026-03-10', 'image' => 'img-imgrefw2.png', 'order' => 1],
            ['title' => 'WORKS C', 'slug' => 'works-c', 'category' => 'branding', 'date' => '2026-02-22', 'image' => 'img-imgrefw3.png', 'order' => 2],
        ];
        foreach ($works as $row) {
            $media = $this->importMedia($row['image'], $row['title']);
            $base = CarbonImmutable::parse($row['date'])->setTime(12, 0);
            if ($base->isFuture()) {
                $base = CarbonImmutable::now()->subDay();
            }
            Work::query()->updateOrCreate(['slug' => $row['slug']], [
                'title' => $row['title'],
                'category' => $row['category'],
                'excerpt' => null,
                'body' => '',
                'completed_at' => $row['date'],
                'status' => 'published',
                'published_at' => $base->subDays($row['order']),
                'main_image_id' => $media?->id,
                'seo_title' => null,
                'seo_description' => null,
            ]);
        }
    }

    /** database/seeders/figma-import/ の画像を Media として取り込む（冪等・unit テスト時はスキップ） */
    private function importMedia(string $filename, string $name): ?Media
    {
        if (app()->runningUnitTests()) {
            return null;
        }
        $existing = Media::query()->firstWhere('name', $name);
        if ($existing !== null) {
            return $existing;
        }
        $sourcePath = database_path('seeders/figma-import/'.$filename);
        if (! is_file($sourcePath)) {
            return null;
        }
        $disk = Storage::disk((string) config('agentcms.uploads.disk'));
        $storedPath = 'media/figma-'.$filename;
        $disk->put($storedPath, (string) file_get_contents($sourcePath));
        $dimensions = getimagesize($sourcePath);

        return Media::query()->create([
            'name' => $name,
            'alt' => $name,
            'path' => $storedPath,
            'mime' => $dimensions !== false ? (string) $dimensions['mime'] : 'image/png',
            'size' => (int) $disk->size($storedPath),
            'width' => $dimensions !== false ? (int) $dimensions[0] : 0,
            'height' => $dimensions !== false ? (int) $dimensions[1] : 0,
            'has_webp' => false,
        ]);
    }
}
